CREATE SCHEMA IF NOT EXISTS agenda;

CREATE TABLE agenda.slot (
    id            UUID                     NOT NULL,
    specialist_id UUID                     NOT NULL,
    specialty     VARCHAR(100)             NOT NULL,
    start_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    end_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_slot_specialist_start UNIQUE (specialist_id, start_at),
    CONSTRAINT ck_slot_range CHECK (end_at > start_at)
);
CREATE INDEX idx_slot_specialty_start ON agenda.slot (specialty, start_at);

-- id is generated by the client (offline-first), so a retry reuses it.
-- The unique slot_id is what prevents double booking: the database decides, not the application.
CREATE TABLE agenda.booking (
    id         UUID                     NOT NULL,
    slot_id    UUID                     NOT NULL,
    patient_id UUID                     NOT NULL,
    booked_by  UUID                     NOT NULL,
    booked_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_booking_slot UNIQUE (slot_id),
    CONSTRAINT fk_booking_slot FOREIGN KEY (slot_id) REFERENCES agenda.slot (id)
);
